package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewScanner(os.Stdin)
	if !in.Scan() {
		return
	}
	s := in.Text()
	chars := []rune(s)
	size := len(chars)
	middle := (size - 1) / 2

	odd := size%2 != 0

	j := size - 1
	i := 0
	counter := 1

	palindrom := true
	for {
		begin := chars[i]
		end := chars[j]
		if begin != end {
			if counter == 0 {
				palindrom = false
				break
			}
			counter--
		}
		if i == middle {
			break
		}
		i++
		j--
	}
	if (palindrom && counter == 0) || (palindrom && counter == 1 && odd) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

